<?php
defined( 'ABSPATH' ) || exit;
$form = isset( $form ) && is_array( $form ) ? $form : array();
$fields = $form['fields'] ?? array();
$images = $form['images'] ?? array();
$gallery = $form['gallery'] ?? array();
$cover_id = $form['featured_media'] ?? 0;
$cover = $images[ $cover_id ] ?? null;
$errors = isset( $errors ) && is_array( $errors ) ? $errors : array();
$published = ( $form['publication'] ?? 'draft' ) === 'publish';
$id = $form['id'] ?? 0;
$render_input = static function ( $name, $label, $type = 'text', $hint = '', $attrs = '' ) use ( $fields, $errors ) {
?>
<div class="gestion-field"><label for="<?php echo esc_attr( $name ); ?>"><?php echo esc_html( $label ); ?></label><input id="<?php echo esc_attr( $name ); ?>" name="<?php echo esc_attr( $name ); ?>" type="<?php echo esc_attr( $type ); ?>" value="<?php echo esc_attr( $fields[ $name ] ?? '' ); ?>" <?php echo $attrs; /* Trusted static attributes from calls below. */ ?> aria-describedby="<?php echo esc_attr( $name . '-error' ); ?>" <?php echo isset( $errors[ $name ] ) ? 'aria-invalid="true"' : ''; ?>><?php if ( $hint ) : ?><small><?php echo esc_html( $hint ); ?></small><?php endif; ?><span class="gestion-field-error" id="<?php echo esc_attr( $name . '-error' ); ?>" data-error-for="<?php echo esc_attr( $name ); ?>"><?php echo esc_html( $errors[ $name ] ?? '' ); ?></span></div>
<?php }; ?>
<a href="<?php echo esc_url( $management_url ); ?>" class="gestion-back">Volver al stock</a>
<div class="gestion-page-heading"><div><h1><?php echo $id ? 'Editar vehículo' : 'Cargar vehículo'; ?></h1><p><?php echo $published ? 'Los cambios se reflejan en la ficha al guardar.' : 'Podés guardar incompleto y publicar cuando esté listo.'; ?></p></div><span class="gestion-state publication-label"><?php echo $published ? 'Publicado' : 'Borrador'; ?></span></div>
<form id="vehicle-form" method="post" enctype="multipart/form-data" class="gestion-editor" action="<?php echo esc_url( $config['formAction'] ?? '' ); ?>">
<input type="hidden" name="action" value="save"><input type="hidden" name="csrf" value="<?php echo esc_attr( $config['csrf'] ?? '' ); ?>"><input type="hidden" name="vehicle_id" value="<?php echo esc_attr( $id ); ?>"><input type="hidden" name="revision" value="<?php echo esc_attr( $form['revision'] ?? '' ); ?>"><input type="hidden" name="publication" value="<?php echo esc_attr( $form['publication'] ?? 'draft' ); ?>"><input type="hidden" name="featured_media" value="<?php echo esc_attr( $cover_id ); ?>">
<div class="gestion-editor-sections">
<section class="gestion-form-section" aria-labelledby="main-data"><div class="gestion-section-heading"><h2 id="main-data">Datos principales</h2><p>El nombre de la unidad se genera con estos datos.</p></div><div class="gestion-fields-grid">
<?php $render_input( 'rp_marca', 'Marca', 'text', '', 'autocomplete="off" maxlength="100"' ); $render_input( 'rp_modelo', 'Modelo', 'text', '', 'autocomplete="off" maxlength="100"' ); $render_input( 'rp_version', 'Versión', 'text', 'Opcional', 'maxlength="150"' ); $render_input( 'rp_anio', 'Año', 'number', '', 'min="1900" step="1" inputmode="numeric"' ); ?>
</div></section>
<section class="gestion-form-section" aria-labelledby="price-data"><div class="gestion-section-heading"><h2 id="price-data">Precio y estado</h2><p>El precio se muestra únicamente en la ficha pública.</p></div><div class="gestion-fields-grid">
<?php $render_input( 'rp_precio_monto', 'Precio', 'number', 'Opcional', 'min="0" step="0.01" inputmode="decimal"' ); ?>
<div class="gestion-field"><label for="rp_precio_moneda">Moneda</label><select name="rp_precio_moneda" id="rp_precio_moneda"><option value="">Elegir moneda</option><?php $currencies = array( 'ARS' => 'ARS — Pesos', 'USD' => 'USD — Dólares' ); $legacy = $fields['rp_precio_moneda'] ?? ''; if ( $legacy && ! isset( $currencies[ $legacy ] ) ) { $currencies[ $legacy ] = $legacy . ' — Moneda existente'; } foreach ( $currencies as $value => $label ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( $legacy, $value ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select><span class="gestion-field-error" data-error-for="rp_precio_moneda"><?php echo esc_html( $errors['rp_precio_moneda'] ?? '' ); ?></span></div>
<div class="gestion-field"><label for="rp_estado_stock">Estado comercial</label><select name="rp_estado_stock" id="rp_estado_stock"><option value="">Elegir estado</option><?php foreach ( array( 'disponible' => 'Disponible', 'reservado' => 'Reservado', 'vendido' => 'Vendido' ) as $value => $label ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( $fields['rp_estado_stock'] ?? '', $value ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select><span class="gestion-field-error" data-error-for="rp_estado_stock"><?php echo esc_html( $errors['rp_estado_stock'] ?? '' ); ?></span></div>
<?php $render_input( 'rp_kilometraje', 'Kilometraje', 'number', 'Opcional · km', 'min="0" step="1" inputmode="numeric"' ); ?>
</div></section>
<?php if ( ( $fields['rp_estado_stock'] ?? '' ) !== 'vendido' ) : ?><noscript><label class="gestion-confirm-sold"><input type="checkbox" name="confirm_sold" value="1"><span>Si elegís Vendido, confirmo que dejará de aparecer en el catálogo y no se eliminará.</span></label></noscript><?php endif; ?>
<section class="gestion-form-section" aria-labelledby="photos-data"><div class="gestion-section-heading"><h2 id="photos-data">Fotos</h2><p>JPG, PNG o WebP · Hasta 12 MiB por foto y 20 imágenes en total.</p></div>
<div class="gestion-media-error gestion-field-error" data-error-for="featured_media"><?php echo esc_html( $errors['featured_media'] ?? '' ); ?></div>
<div class="gestion-cover-layout"><div class="gestion-cover" data-cover-preview><?php if ( $cover ) : ?><img src="<?php echo esc_url( $cover['url'] ); ?>" alt="Foto principal" width="640" height="480"><?php else : ?><span>Tu foto principal aparecerá acá</span><?php endif; ?></div><div class="gestion-cover-controls"><h3>Foto principal</h3><p>La primera imagen que se verá en el catálogo.</p><label class="gestion-button secondary gestion-file-label" for="cover_file"><?php echo $cover ? 'Reemplazar foto' : 'Subir foto principal'; ?></label><input id="cover_file" name="cover_file" type="file" accept="image/jpeg,image/png,image/webp" data-upload-cover><button type="button" class="gestion-quiet" data-remove-cover hidden>Quitar portada</button><p class="gestion-help">También podés arrastrar una foto al recuadro desde tu computadora.</p></div></div>
<div class="gestion-gallery-heading"><div><h3>Galería</h3><p>Agregá otras vistas y ordenalas como querés que aparezcan.</p></div><label class="gestion-button secondary gestion-file-label" for="gallery_files">Agregar fotos</label></div>
<input id="gallery_files" name="gallery_files[]" type="file" multiple accept="image/jpeg,image/png,image/webp" data-upload-gallery>
<div class="gestion-gallery" data-gallery><?php foreach ( $gallery as $image_id ) : $image = $images[ $image_id ] ?? null; if ( ! $image ) { continue; } ?><div class="gestion-photo" data-image-id="<?php echo esc_attr( $image_id ); ?>"><img src="<?php echo esc_url( $image['thumb'] ?? $image['url'] ); ?>" alt="<?php echo esc_attr( $image['alt'] ?? 'Imagen de galería' ); ?>" width="240" height="180"><input type="hidden" name="gallery[]" value="<?php echo esc_attr( $image_id ); ?>"></div><?php endforeach; ?></div>
<div data-upload-queue class="gestion-upload-queue" aria-live="polite"></div><span class="gestion-field-error" data-error-for="gallery"><?php echo esc_html( $errors['gallery'] ?? '' ); ?></span>
<noscript><p class="gestion-help">Las fotos seleccionadas se subirán al guardar. Para ordenar o quitar imágenes existentes, activá JavaScript.</p></noscript>
</section>
<section class="gestion-form-section" aria-labelledby="additional-data"><div class="gestion-section-heading"><h2 id="additional-data">Información adicional</h2><p>Opcional. Agregá sólo información real de esta unidad.</p></div><label for="description">Descripción</label><textarea id="description" name="description" rows="6" maxlength="20000"><?php echo esc_textarea( $form['description'] ?? '' ); ?></textarea><span class="gestion-field-error" data-error-for="description"><?php echo esc_html( $errors['description'] ?? '' ); ?></span></section>
</div>
<aside class="gestion-editor-summary"><div class="gestion-summary-inner"><h2>La unidad</h2><p class="gestion-summary-title" data-title-preview><?php echo esc_html( $form['title'] ?? 'Completá marca y modelo' ); ?></p><p class="gestion-help">Marca, modelo, año, estado y foto principal son necesarios para publicar.</p><div class="gestion-save-actions"><?php if ( $published ) : ?><button type="submit" name="intent" value="save" class="gestion-button primary">Guardar cambios</button><?php else : ?><button type="submit" name="intent" value="publish" class="gestion-button primary">Publicar vehículo</button><button type="submit" name="intent" value="draft" class="gestion-button secondary">Guardar borrador</button><?php endif; ?></div><p data-save-status class="gestion-save-status" role="status" aria-live="polite">Sin cambios pendientes</p><a data-public-link href="<?php echo esc_url( $form['url'] ?? '' ); ?>" target="_blank" rel="noopener" <?php echo ! $published || empty( $form['url'] ) ? 'hidden' : ''; ?>>Ver ficha pública</a></div></aside>
</form>
<script type="application/json" id="vehicle-data"><?php echo wp_json_encode( $form, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT ); ?></script>
<dialog class="gestion-dialog" id="session-dialog"><h2>Volvé a iniciar sesión</h2><p>Tus cambios siguen en este formulario. Ingresá de nuevo en otra pestaña y después continuá acá.</p><a class="gestion-button primary" href="<?php echo esc_url( add_query_arg( 'reauth', '1', $management_url ) ); ?>" target="_blank" rel="noopener">Iniciar sesión</a><button class="gestion-button secondary" type="button" data-session-retry>Ya ingresé, continuar</button><button class="gestion-quiet" type="button" data-dialog-close>Volver al formulario</button></dialog>
